// KMP STRING MATCHING — O(n+m)
function kmpSearch(text, pattern) {
    const n = text.length, m = pattern.length;
    if (m === 0) return [0];

    // BUILD FAILURE FUNCTION (lps array)
    const lps = new Array(m).fill(0);
    let l = 0; // length of previous longest prefix suffix
    let r = 1;
    while (r < m) {
        if (pattern[r] === pattern[l]) {
            lps[r] = l + 1;
            l++; r++;
        } else if (l > 0) {
            l = lps[l-1]; // backtrack l using lps
        } else {
            lps[r] = 0; // no proper prefix suffix
            r++;
        }
    }

    // MATCHING using lps
    const occurrences = [];
    let i = 0; // text pointer
    let j = 0; // pattern pointer
    while (i < n) {
        if (text[i] === pattern[j]) {
            i++; j++;
        }
        if (j === m) {
            occurrences.push(i - j); // match found at index i-j
            j = lps[j-1];            // jump: find next match
        } else if (i < n && text[i] !== pattern[j]) {
            if (j > 0) j = lps[j-1]; // use failure function
            else i++;                  // no match, advance text
        }
    }
    return occurrences;
}

