// RABIN-KARP ROLLING HASH — O(n+m) average
function rabinKarpSearch(text, pattern) {
    const n = text.length, m = pattern.length;
    if (m > n) return [];
    const BASE = 31, MOD = 1e9 + 7;

    // Precompute BASE^(m-1) mod MOD
    let highPow = 1;
    for (let i = 0; i < m-1; i++) highPow = (highPow * BASE) % MOD;

    // Compute pattern hash and first window hash
    let patHash = 0, winHash = 0;
    for (let i = 0; i < m; i++) {
        patHash = (patHash * BASE + pattern.charCodeAt(i)) % MOD;
        winHash = (winHash * BASE + text.charCodeAt(i)) % MOD;
    }

    const results = [];

    for (let i = 0; i <= n - m; i++) {
        if (winHash === patHash) {
            // VERIFY: hash match, check characters (handle collision)
            if (text.slice(i, i+m) === pattern) results.push(i);
        }
        // ROLL: remove leftmost, add rightmost
        if (i < n - m) {
            winHash = (winHash - text.charCodeAt(i) * highPow % MOD + MOD) % MOD;
            winHash = (winHash * BASE + text.charCodeAt(i+m)) % MOD;
        }
    }
    return results;
}

console.log(rabinKarpSearch('aabxaabaab', 'aab')); // [0, 5, 7]

// MULTI-PATTERN RABIN-KARP
function multiPatternSearch(text, patterns) {
    const m = patterns[0].length; // assume same length for simplicity
    const BASE = 31, MOD = 1e9 + 7;
    const n = text.length;

    // Build hash set of pattern hashes
    const patHashes = new Map(); // hash -> [pattern]
    for (const p of patterns) {
        let h = 0;
        for (const c of p) h = (h * BASE + c.charCodeAt(0)) % MOD;
        if (!patHashes.has(h)) patHashes.set(h, []);
        patHashes.get(h).push(p);
    }

    // Slide window over text
    let highPow = 1;
    for (let i = 0; i < m-1; i++) highPow = (highPow * BASE) % MOD;
    let winHash = 0;
    for (let i = 0; i < m; i++) winHash = (winHash * BASE + text.charCodeAt(i)) % MOD;

    const results = [];
    for (let i = 0; i <= n - m; i++) {
        if (patHashes.has(winHash)) {
            const window = text.slice(i, i+m);
            for (const p of patHashes.get(winHash)) {
                if (window === p) results.push({pos:i, pattern:p});
            }
        }
        if (i < n-m) {
            winHash = (winHash - text.charCodeAt(i)*highPow%MOD + MOD) % MOD;
            winHash = (winHash * BASE + text.charCodeAt(i+m)) % MOD;
        }
    }
    return results;
}

