// Z-ALGORITHM — O(n)
function zFunction(s) {
    const n = s.length;
    const Z = new Array(n).fill(0);
    Z[0] = n; // by convention
    let l = 0, r = 0; // current Z-box [l, r]

    for (let i = 1; i < n; i++) {
        if (i < r) {
            // i is inside the Z-box: use previous Z value as lower bound
            Z[i] = Math.min(r - i, Z[i - l]);
        }
        // Naive extension beyond what we know
        while (i + Z[i] < n && s[Z[i]] === s[i + Z[i]]) {
            Z[i]++;
        }
        // Update Z-box if we extended beyond r
        if (i + Z[i] - 1 > r) {
            l = i;
            r = i + Z[i] - 1;
        }
    }
    return Z;
}

