// STRING MATCHING USING Z-ALGORITHM
function zSearch(text, pattern) {
    const combined = pattern + '$' + text; // '$' as separator
    const Z = zFunction(combined);
    const m = pattern.length;
    const results = [];
    for (let i = m + 1; i < combined.length; i++) {
        if (Z[i] === m) results.push(i - m - 1); // found at text position i-m-1
    }
    return results;
}

