// SUFFIX ARRAY — O(n log^2 n) implementation (simpler than O(n log n) pure doubling)
function buildSuffixArray(s) {
    const n = s.length;
    // Create suffix indices and sort them by suffix comparison
    const SA = Array.from({length:n}, (_,i)=>i);
    SA.sort((a, b) => {
        // Compare suffixes starting at a and b
        if (s.slice(a) < s.slice(b)) return -1;
        if (s.slice(a) > s.slice(b)) return 1;
        return 0;
    });
    return SA;
}
// Note: SA.sort with s.slice comparison is O(n^2 log n)
// For O(n log^2 n): use radix sort with rank pairs (not shown for clarity)

// LCP ARRAY using Kasai's algorithm — O(n)
function buildLCP(s, SA) {
    const n = s.length;
    const rank = new Array(n); // rank[i] = position of suffix i in SA
    for (let i = 0; i < n; i++) rank[SA[i]] = i;

    const lcp = new Array(n).fill(0);
    let h = 0; // current LCP length

    for (let i = 0; i < n; i++) {
        if (rank[i] > 0) {
            const j = SA[rank[i] - 1]; // previous suffix in SA order
            while (i + h < n && j + h < n && s[i+h] === s[j+h]) h++;
            lcp[rank[i]] = h;
            if (h > 0) h--; // Kasai's key: LCP can only decrease by 1
        }
    }
    return lcp;
}

