// LONGEST REPEATED SUBSTRING using SA + LCP
function longestRepeatedSubstring(s) {
    const SA = buildSuffixArray(s);
    const lcp = buildLCP(s, SA);
    const maxLCP = Math.max(...lcp);
    if (maxLCP === 0) return '';
    const idx = lcp.indexOf(maxLCP);
    return s.slice(SA[idx], SA[idx] + maxLCP);
}
