// AHO-CORASICK MULTI-PATTERN SEARCH
class AhoCorasick {
    constructor() {
        this.root = { children:{}, fail:null, output:[] };
    }

    // INSERT all patterns into the Trie
    insert(pattern, id) {
        let node = this.root;
        for (const c of pattern) {
            if (!node.children[c]) node.children[c] = { children:{}, fail:null, output:[] };
            node = node.children[c];
        }
        node.output.push(id); // mark end of pattern
    }

    // BUILD failure links via BFS — O(M)
    build() {
        const queue = [];
        // Root's children: fail -> root
        for (const c in this.root.children) {
            this.root.children[c].fail = this.root;
            queue.push(this.root.children[c]);
        }
        while (queue.length) {
            const curr = queue.shift();
            for (const c in curr.children) {
                const child = curr.children[c];
                let fail = curr.fail;
                while (fail && !fail.children[c]) fail = fail.fail;
                child.fail = (fail && fail.children[c] !== child) ? fail.children[c] : this.root;
                // Inherit output from failure link (for overlapping patterns)
                child.output = child.output.concat(child.fail.output);
                queue.push(child);
            }
        }
    }

    // SEARCH text for all pattern occurrences — O(n + matches)
    search(text, patterns) {
        const results = []; // {pos, patternId}
        let node = this.root;
        for (let i = 0; i < text.length; i++) {
            const c = text[i];
            while (node !== this.root && !node.children[c]) node = node.fail;
            node = node.children[c] || this.root;
            for (const id of node.output) {
                results.push({ end: i, pattern: patterns[id] });
            }
        }
        return results;
    }
}

