// SHORTEST PALINDROME (#214) using KMP:
function shortestPalindrome(s) {
    const rev = s.split('').reverse().join('');
    const combined = s + '#' + rev;
    // Build KMP failure function on combined
    const m = combined.length;
    const lps = new Array(m).fill(0);
    let l = 0, r = 1;
    while (r < m) {
        if (combined[r] === combined[l]) { lps[r]=l+1; l++; r++; }
        else if (l>0) l = lps[l-1];
        else { lps[r]=0; r++; }
    }
    // lps[m-1] = length of longest palindromic prefix of s
    const palindromicPrefixLen = lps[m-1];
    // Add the non-palindromic suffix (reversed) to the front
    return rev.slice(0, s.length - palindromicPrefixLen) + s;
}
